function renderGcd(){const x=gcdQuestions[gIndex];if(!x)return;document.querySelector('#question-number4').textContent=(gIndex+1)+' / 10';document.querySelector('#level4').textContent=dict().level[x.l];document.querySelector('#question4').textContent=x.q[lang()];const box=document.querySelector('#answers4');box.innerHTML='';x.a.forEach((answer,i)=>{const b=document.createElement('button');b.textContent=Array.isArray(answer)?answer[lang()]:answer;b.addEventListener('click',()=>chooseGcd(i,b));box.appendChild(b)});document.querySelector('#feedback4').textContent='';document.querySelector('#feedback4').className='';document.querySelector('#next4').hidden=true;gAnswered=false}
