function gradeAdvice(grade){const lat=['Potrebno je ponoviti celu oblast.','Ponovi osnovna pravila i lakše zadatke.','Znanje je dobro; uvežbaj NZD, NZS i složenije zadatke.','Vrlo dobro znanje; proveri samo zadatke u kojima nisi bio siguran.','Odlično vladaš celom oblašću.'],cyr=['Потребно је поновити целу област.','Понови основна правила и лакше задатке.','Знање је добро; увежбај НЗД, НЗС и сложеније задатке.','Врло добро знање; провери само задатке у којима ниси био сигуран.','Одлично владаш целом облашћу.'];return(script==='latn'?lat:cyr)[grade-1]}
function setsGradeAdvice(grade){const lat=['Ponovi svih pet lekcija, počevši od osnovnih oznaka i elemenata skupa.','Razumeš osnove; ponovi podskup, jednakost i osnovne operacije sa skupovima.','Znanje je dobro; dodatno uvežbaj razliku skupova, Venove dijagrame i tekstualne zadatke.','Vrlo dobro znanje; proveri samo složenije zadatke sa brojem elemenata skupova.','Odlično vladaš skupovima i njihovom primenom.'],cyr=['Понови свих пет лекција, почевши од основних ознака и елемената скупа.','Разумеш основе; понови подскуп, једнакост и основне операције са скуповима.','Знање је добро; додатно увежбај разлику скупова, Венове дијаграме и текстуалне задатке.','Врло добро знање; провери само сложеније задатке са бројем елемената скупова.','Одлично владаш скуповима и њиховом применом.'];return(script==='latn'?lat:cyr)[grade-1]}
function fractionsGradeAdvice(grade){const lat=['Ponovi osnovne pojmove, vrste razlomaka i sve četiri računske operacije.','Razumeš osnove; ponovi izjednačavanje imenilaca i računanje sa decimalnim brojevima.','Znanje je dobro; dodatno uvežbaj deljenje i mešovite brojevne izraze.','Vrlo dobro znanje; proveri složenije zadatke i pažljivo prati decimalni zarez.','Odlično vladaš razlomcima, decimalnim brojevima i brojevnim izrazima.'],cyr=['Понови основне појмове, врсте разломака и све четири рачунске операције.','Разумеш основе; понови изједначавање именилаца и рачунање са децималним бројевима.','Знање је добро; додатно увежбај дељење и мешовите бројевне изразе.','Врло добро знање; провери сложеније задатке и пажљиво прати децимални зарез.','Одлично владаш разломцима, децималним бројевима и бројевним изразима.'];return(script==='latn'?lat:cyr)[grade-1]}
